List<int> parseNestedParens(String parenString) {
  final stack = Stack();
  int maxDepth = 0;
  int currentDepth = 0;

  for (final char in parenString.split('')) {
    if (char == '(') {
      currentDepth++;
      stack.add(currentDepth);
      maxDepth = max(maxDepth, currentDepth);
    } else if (char == ')') {
      stack.removeLast();
      currentDepth--;
    }
  }

  return List<int>.filled(maxDepth + 1, 0)
       .map((_) => stack.length > 0 ? stack.last : 0).toList()
       ..sort(); // Sort to ensure ascending order as per the example
}
