String makePalindrome(String stringArg0) {
  if (stringArg0.isEmpty || stringArg0.length == 1) return stringArg0;

  final length = stringArg0.length;
  int leftIndex = 0;
  int rightIndex = length - 1;

  while (leftIndex < rightIndex) {
    if (stringArg0[leftIndex] != stringArg0[rightIndex]) {
      // Find the closest matching character to swap with
      String foundChar = '';
      for (int i = rightIndex; i > leftIndex; i--) {
        if (stringArg0[i] == stringArg0[leftIndex]) {
          foundChar = stringArg0[i];
          break;
        }
      }

      if (foundChar.isNotEmpty) {
        stringArg0 = stringArg0.substring(0, rightIndex) + stringArg0[leftIndex] +
            stringArg0.substring(rightIndex + 1);
        rightIndex--;
        continue;
      } else {
        // No match found, add a wildcard and move both pointers inward
        stringArg0 += stringArg0[leftIndex];
        stringArg0 = stringArg0.replaceRange(leftIndex, leftIndex + 1, '*');
        leftIndex++;
        rightIndex--;
        continue;
      }
    }
    leftIndex++;
    rightIndex--;
  }

  return stringArg0;
}
