List<String> allPrefixes(String string) {
  List<String> prefixes = [];

  if (string.isEmpty) return prefixes;

  for (int i = 1; i <= string.length; i++) {
    String prefix = string.substring(0, i);

    // Check if the current character is a valid start of a new word
    bool isValidStart = false;
    int j = i - 1;
    while (j >= 0 && !isValidStart) {
      char c = string[j];

      // A valid start is when we hit an uppercase letter or a lowercase letter that's not part of a multi-letter sequence like "abc" 
      if ((c.isUpperCase() || (c.isLowerCase() && j == i - 1)) ) { 
        isValidStart = true;

        // If it's lowercase and not at the end, check previous characters to see if they are part of a multi-letter abbreviation
        if (c.isLowerCase() && j != i - 1) {
          int k = j - 1;
          while (k >= 0 && k > j - 3) {
            if (!string[k].isLowerCase()) break;
            k--;
          }

          if (k >= 0 && k < j - 2) {
            isValidStart = false;
            break;
          } else {
            isValidStart = true;
          }
        }
      }
      j--;
    }

    if (isValidStart) {
      prefixes.add(prefix);
    }
  }

  return prefixes;
