List<int> parseMusic(String musicString) {
  final List<String> notes = ['C', 'D', 'E', 'F', 'G', 'A', 'B'];
  int index = 0;
  List<int> result = [];

  while (index < musicString.length) {
    if (musicString[index] == ' ') {
      index++;
      continue;
    }

    // Check for accidental symbols
    bool isSharp = false;
    bool isFlat = false;

    if (index + 1 < musicString.length && 
        (musicString[index + 1] == '#' || musicString[index + 1] == '♯')) {
      isSharp = true;
      index += 2;
    } else if (index + 1 < musicString.length && 
               (musicString[index + 1] == 'b' || musicString[index + 1] == '♭')) {
      isFlat = true;
      index += 2;
    } else {
      index++;
    }

    // Determine the note name
    String noteName = '';
    while (index < musicString.length && !notes.contains(musicString[index])) {
      noteName += musicString[index];
      index++;
    }

    if (noteName.isEmpty) return [];

    // Find the base note position in the list of notes
    int baseIndex = -1;
    for (int i = 0; i < notes.length; i++) {
      if (notes[i].toLowerCase() == noteName.toLowerCase()) {
        baseIndex = i;
        break;
      }
    }

    if (baseIndex == -1) return [];

    // Adjust for sharps and flats
    int adjustedIndex = baseIndex;
    if (isSharp) adjustedIndex = (adjustedIndex + 1) % 7;
    if (isFlat) adjustedIndex = (adjustedIndex - 1 + 7) % 7;

    // Convert to MIDI note number, assuming A4=69
    int midiNoteNumber = (adjustedIndex - 9 + 12) * 12 + 69;
    result.add(midiNoteNumber);
  }

  return result;
}
