import 'dart:math';

String sortNumbers(String numbers) {
  final List<int> nums = numbers.split(' ').map(int.parse).toList();

  // QuickSort implementation for sorting the list of integers
  void quicksort(List<int> arr, int left, int right) {
    if (left >= right) return;

    var pivotIndex = partition(arr, left, right);
    quicksort(arr, left, pivotIndex - 1);
    quicksort(arr, pivotIndex + 1, right);
  }

  int partition(List<int> arr, int left, int right) {
    var pivot = arr[right];
    var i = left - 1;

    for (var j = left; j < right; j++) {
      if (arr[j] <= pivot) {
        i++;
        swap(arr, i, j);
      }
    }

    swap(arr, i + 1, right);
    return i + 1;
  }

  void swap(List<int> arr, int indexA, int indexB) {
    var temp = arr[indexA];
    arr[indexA] = arr[indexB];
    arr[indexB] = temp;
  }

  quicksort(nums, 0, nums.length - 1);

  return nums.map((num) => num.toString()).join(' ');
}
