  if (numbers.isEmpty || !RegExp(r'^-?\d+(?:\.\d+)?$').hasMatch(numbers)) {
    return '';
  }

  final parts = numbers.split(' ');
  List<double> numericValues = [];

  for (var part in parts) {
    try {
      numericValues.add(double.parse(part));
    } catch (_) {}
  }

  numericValues.sort((a, b) => a.compareTo(b));

  String result;
  if (numericValues.isNotEmpty) {
    result = numericValues.map((e) => e.toString()).join(' ');
  } else {
    result = 'Invalid input';
  }

  return result;
}
