int largestDivisor(int n) {
  if (n == 0) return 0;
  int maxDiv = 1;
  for (int i = 2; i <= sqrt(n); i++) {
    if (n % i == 0) {
      maxDiv = i;
    }
  }
  if (maxDiv > 1 && n != maxDiv) {
    return n ~/ maxDiv;
  } else if (maxDiv > 1) {
    return maxDiv;
  } else {
    return 1;
  }
}
