// This is the Dart code that implements a function to find the largest divisor of a number.
// The function checks from the square root down to 2, returning the first divisor it finds.

import 'dart:math';

int largestDivisor(int n) {
  // If n is less than 2, there are no divisors other than 1 and itself.
  if (n < 2) {
    return -1;
  }

  // Calculate the integer part of the square root of n.
  int sqrtN = sqrt(n).floor();

  // Check each possible divisor starting from the square root downwards.
  for (int i = sqrtN; i >= 2; i--) {
    if (n % i == 0) {
      // Return the first divisor found, which will be the largest one since we're checking in descending order.
      return i;
    }
  }

  // If no divisors were found, the number is prime. The only divisors are 1 and itself,
  // so the largest proper divisor is 1.
  return 1;
}

void main() {
  print(largestDivisor(49));   // Output: 7
  print(largestDivisor(35));   // Output: 7
  print(largestDivisor(89));   // Output: 1
  print(largestDivisor(60));   // Output: 30
  print(largestDivisor(100));  // Output: 50
}
