List<int> sortThird(List<int> l) {
  if (l.length < 3) return List.from(l);

  final n = l.length;
  for (int i = 0; i <= n - 3; i += 1) {
    int j, k, idx;

    // Find the index of the minimum element in l[i..n-1]
    idx = i;
    for (j = i + 1; j < n; ++j)
      if (l[j] < l[idx]) idx = j;

    // Swap with the first position
    if (idx != i) {
      var temp = l[i];
      l[i] = l[idx];
      l[idx] = temp;
    }

    // Now find the index of the second minimum and swap it to i+1
    idx = i + 1;
    for (j = i + 2; j < n; ++j)
      if (l[j] < l[idx]) idx = j;

    if (idx != i + 1) {
      var temp = l[i + 1];
      l[i + 1] = l[idx];
      l[idx] = temp;
    }

    // Now find the third minimum and swap it to i+2
    idx = i + 2;
    for (j = i + 3; j < n; ++j)
      if (l[j] < l[idx]) idx = j;

    if (idx != i + 2) {
      var temp = l[i + 2];
      l[i + 2] = l[idx];
      l[idx] = temp;
    }
  }

  return l;
}

