import 'dart:math';

List<int> sortEven(List<int> l) {
  if (l.isEmpty || l.length == 1) return l;

  List<int> evenIndices = [];
  for (int i = 0; i < l.length; i += 2) {
    evenIndices.add(l[i]);
  }

  int n = evenIndices.length;
  void swap(int a, int b) {
    final temp = evenIndices[a];
    evenIndices[a] = evenIndices[b];
    evenIndices[b] = temp;
  }

  bool isSorted = false;
  while (!isSorted) {
    isSorted = true;
    for (int i = 0; i < n - 1; i++) {
      if (evenIndices[i] > evenIndices[i + 1]) {
        swap(i, i + 1);
        isSorted = false;
      }
    }
  }

  int index = 0;
  for (int i = 0; i < l.length; i += 2) {
    l[i] = evenIndices[index++];
  }

  return l;
}
