    for (int i = 0; i < n; i++) {
      if (currentTime >= timeLimit) break;

      // Update position based on current speed
      positions[i] += speeds[i];

      // Check collision with any other car
      for (int j = i + 1; j < n; j++) {
        if (positions[i] == positions[j]) {
          hasCollided = true;
          print("Collision occurred at time $currentTime");
          break;
        }
      }
    }

    currentTime += 0.001; // Increment time by 1 millisecond
  } while (!hasCollided && currentTime <= timeLimit);

  return hasCollided ? 1 : 0;
