import 'package:flutter/foundation.dart' show kIsWeb;

// Helper function to check valid bracketing
bool isValidBrackets(String input) {
  // Base case - empty string is valid
  if (input.isEmpty) return true;

  int openCount = 0;

  for (final c in input.split('')) {
    switch(c) {
      case '(':
        openCount++;
        break;
      case ')':
        openCount--;
        if (openCount < 0) return false;
        break;
      case '[':
        openCount += 2;
        break;
      case ']':
        openCount -= 2;
        if (openCount < 0) return false;
        break;
      case '{':
        openCount += 3;
        break;
      case '}':
        openCount -= 3;
        if (openCount < 0) return false;
        break;
      default:
        // Ignore other characters
        continue;
    }
  }

  return openCount == 0;
}

// Main function with error handling
