String antiShuffle(String s) {
  if (s.isEmpty) return '';

  final List<String> words = s.split(' ');
  int wordCount = words.length;

  // Randomly select a permutation of the indices from 0 to wordCount - 1
  final List<int> shuffledIndices = List.generate(wordCount, (i) => i);
  for (int i = wordCount - 1; i > 0; i--) {
    final int j = Random().nextInt(i + 1);
    final int temp = shuffledIndices[i];
    shuffledIndices[i] = shuffledIndices[j];
    shuffledIndices[j] = temp;
  }

  // Reconstruct the string using the shuffled indices
  String result = '';
  for (final index in shuffledIndices) {
    result += words[index] + ' ';
  }
  return result.trim();
}
