        wordStartIndex = i;
        inWord = true;
      }
      currentWord += char;
    } else {
      if (inWord) {
        result.add(currentWord);
        currentWord = '';
        inWord = false;
      }

      // Handle non-letter characters that are not spaces, e.g., punctuation
      if (char != ' ') {
        result.add(char);
      }
    }
  }

  // Add the last word if we're still in a word
  if (inWord) {
    result.add(currentWord);
  }

  // Reconstruct the string with words sorted alphabetically within each group
  return result.map((word) => sortLetters(word)).join('');
}

String sortLetters(String word) {
