      var nextEnd = input.indexOf(' ', lastIndex + 1);
      if (nextEnd == -1) {
        nextEnd = input.length;
      }

      var substring = input.substring(lastIndex, nextEnd);
      if (tagPattern.hasMatch(substring)) {
        currentHash = substring;
      } else {
        currentHash = '';
      }
    }

    if (currentHash.isNotEmpty) {
      tags.add(currentHash);
    }

    return tags.isNotEmpty;
