int multiply(int a, int b) {
  if (a == 0 || b == 0) return 0;

  // Determine the sign of the result
  bool isNegative = ((a < 0 && b > 0) || (a > 0 && b < 0));

  // Convert to positive numbers for calculation
  final absA = a.abs();
  final absB = b.abs();

  // Calculate using bitwise operations and addition
  int product = 0;
  while (absB != 0) {
    if (absB & 1 != 0) {
      product += absA;
    }
    absA <<= 1;
    absB >>= 1;
  }

  return isNegative ? -product : product;
}

