// Helper function to calculate factorial using recursive approach
int factorial(int n) {
  if (n == 0) return 1;
  return n * factorial(n - 1);
}

// Function to calculate combination C(n, k)
int chooseNum(int x, int y) {
  if (x < 0 || y < 0) return -1;
  if (y > x) return 0;

  final n = max(x, y);
  final k = min(x, y);

  // Calculate combination using factorials
  return factorial(n) ~/ (factorial(k) * factorial(n - k));
}
