import 'dart:math';

int maxFill(List<List<int>> grid, int capacity) {
  final rows = grid.length;
  if (rows == 0 || grid[0].length == 0) return 0;

  final cols = grid[0].length;

  // Initialize a matrix to track the number of water added at each cell
  List<List<int>> dp = List.generate(rows, (_) => List.filled(cols, 0));

  // Fill the first row and first column with their respective values
  for (var i = 0; i < rows; i++) {
    dp[i][0] = min(grid[i][0], capacity);
  }
  for (var j = 1; j < cols; j++) {
    dp[0][j] = min(grid[0][j], capacity);
  }

  // Process remaining cells in top-down manner
  for (var i = 1; i < rows; i++) {
    for (var j = 1; j < cols; j++) {
      var currentWater = grid[i][j];
      var left = dp[i][j - 1];   // Water from left neighbor
      var up = dp[i - 1][j];     // Water from upper neighbor

      // Determine how much can be filled considering both directions
      if (left >= up) {
        dp[i][j] = min(currentWater + up, capacity);
      } else {
        dp[i][j] = min(currentWater + left, capacity);
      }

      // If we've reached capacity, no more filling is possible
      if (dp[i][j] == capacity) {
        break;
      }
    }

    // Early exit optimization if full fill has been achieved
    if (dp[i][cols-1] == capacity) {
      break;
    }
  }

  // Return the total amount filled
  return dp.last.reduce((a, b) => a + b); 
}
