String matchParens(List<String> lst) {
  final List<String> openers = ['(', '[', '{'];
  final Map<String, String> closers = {'(': ')', '[': ']', '{': '}'}; 
  final Stack<String> stack = Stack();

  for (var i = 0; i < lst.length; i++) {
    var char = lst[i];

    // If the character is an opener, push it onto the stack.
    if (openers.contains(char)) {
      stack.push(char); 
    } else { 
      // Check if there's a matching opener at the top of the stack. 
      if (!stack.isEmpty() && closers[stack.peek()] == char) {
        stack.pop(); 
      } else {
        return "Mismatch"; 
      }
    }
  }

  return stack.isEmpty ? "Matched" : "Unmatched"; 
}

// Helper function to check if two characters are matched.
bool isMatch(String c1, String c2) {
  return (c1 == "(" && c2 == ")") ||
         (c1 == "[" && c2 == "]") ||
         (c1 == "{" && c2 == "}"); 
}
