List<int> maximum(List<int> arr, int k) {
  if (k <= 0 || k >= arr.length) return List.from(arr);

  final n = arr.length;
  final windowSize = k;
  final result = <int>[];
  final queue = Queue<int>();

  for (var i = 0; i < n; ++i) {
    while (!queue.isEmpty && arr[i] > arr[queue.last]) {
      queue.removeLast();
    }
    queue.add(i);

    // Remove elements out of the current window
    while (queue.first <= i - windowSize) {
      queue.removeFirst();
    }

    // Once we have at least one element in the queue and the window is filled,
    // record the max value
    if (i >= windowSize - 1) {
      result.add(arr[queue.first]);
    }
  }

  return result;
}
