List<int> maximum(List<int> arr, int k) {
  if (arr.isEmpty || k <= 0) return [];

  final n = arr.length;
  if (k >= n) return List.from(arr.reversed);

  final maxHeap = PriorityQueue<int>((a, b) => b.compareTo(a));
  for (int i = 0; i < min(k, n); i++) {
    maxHeap.add(arr[i]);
  }

  final result = [];
  final size = min(n - k, n);

  for (int i = k; i < n; i++) {
    final current = arr[i];

    // If the new element is larger than the smallest in heap,
    // replace it.
    if (current > maxHeap.peek!) {
      maxHeap.remove(maxHeap.peek!);
      maxHeap.add(current);
    }

    // When we've processed all elements up to i, add the top of heap
    if ((i + 1) % k == 0) {
      result.add(maxHeap.poll!);
    }
  }

  while (!maxHeap.isEmpty) {
    result.add(maxHeap.poll!);
  }

  return result;
}
