import 'dart:math';

List<int> minPath(List<List<int>> grid, int k) {
  final rows = grid.length;
  final cols = grid[0].length;

  // Helper function to check if a cell is within bounds
  bool isValid(int r, int c) => r >= 0 && r < rows && c >= 0 && c < cols;

  void dfs(int row, int col, List<int> path, Set<String> visited, int currentSum, int steps, int maxSteps, List<int> result) {
    if (steps == maxSteps) {
      if (currentSum < result[1]) {
        result[0] = row * cols + col; // convert coordinates to index for easy comparison
        result[1] = currentSum;
      }
      return;
    }

    String key = '$row,$col';
    if (!visited.contains(key)) {
      visited.add(key);
      var newSum = currentSum + grid[row][col];

      // Try all four directions
      for (int dr = -1; dr <= 1; dr++) {
        for (int dc = -1; dc <= 1; dc++) {
          if (dr != 0 || dc != 0) { // skip same position
            final nextRow = row + dr;
            final nextCol = col + dc;
            if (isValid(nextRow, nextCol)) {
              dfs(nextRow, nextCol, [grid[nextRow][nextCol]]..addAll(path), visited, newSum, steps + 1, maxSteps, result);
            }
          }
        }
      }
      visited.removeLast();
    }
  }

  // Initialize the result with infinity values
  List<int> result = [-1, int.maxValue];

  // Start from each possible starting point in the first row or first column
  for (int i = 0; i < cols; i++) {
    dfs(0, i, [], {'$0,$i'}, grid[0][i], 0, 0, k, result); 
  }

  return [result[0] ~/ cols, result[0] % cols]; // Convert index back to row and column
}
