  final n = arr.length;

  if (total % 3 != 0) {
    return -2; // Sum is not divisible by 3, cannot arrange into triplets
  }

  final sumEachTriplet = total ~/ 3;

  final requiredCount = sumEachTriplet * 3 / 9;
  final actualCount = countValidTriplets(arr);

  if (actualCount >= requiredCount && actualCount <= (requiredCount + n)) {
    return 1;
  } else {
    return 0;
  }
}

// Helper function to count valid triplets where each triplet sums up to 9 and contains numbers between 5-10
int countValidTriplets(List<int> arr) {
  Map<List<int>, bool> seen = {};
  int count = 0;

  for (int i = 0; i < arr.length; i++) {
    for (int j = i + 1; j < arr.length; j++) {
      for (int k = j + 1; k < arr.length; k++) {
        List<int> triplet = [arr[i], arr[j], arr[k]];
        if (!seen[triplet] && triplet.reduce((a, b) => a + b) == 9) {
          seen.addAll({triplet: true});
          count++;
        }
      }
    }
  }

  return count;
}
