String fixSpaces(String text) {
  if (text == null || text.isEmpty) return '';

  final List<String> parts = [];
  int i = 0;
  while (i < text.length) {
    // Check for spaces at the start of a line, after a newline or before a newline
    bool isStartOfLine = i == 0 || text[i - 1] == '\n';

    if (isStartOfLine && text[i] == ' ') {
      i++;
      continue; // Skip leading space
    }

    // Check for trailing spaces at end of lines
    bool isEndOfLine = i == text.length - 1 || text[i + 1] == '\n';
    if (isEndOfLine && text[i] == ' ') {
      break; // Stop processing as we've reached the end with trailing space
    }

    // Check for multiple consecutive spaces between words
    int j = i;
    while (j < text.length && text[j] == ' ') {
      j++;
    }
    if (j > i + 1) {
      parts.add(' ');
      i = j;
      continue;
    }

    // Regular character handling
    parts.add(text.substring(i, i + 1));
    i++;
  }

  return parts.join('');
}
