String fixSpaces(String text) {
  if (text.isEmpty) return '';

  final List<String> parts = [];
  var currentWord = '';

  for (var i = 0; i < text.length; i++) {
    final char = text[i];

    // Check if the character is a space and the previous was not a space.
    if (char == ' ') {
      if (currentWord.isNotEmpty || parts.last != ' ') {
        parts.add(currentWord);
        currentWord = '';
      }
    } else {
      currentWord += char;
    }
  }

  if (currentWord.isNotEmpty) {
    parts.add(currentWord);
  }

  // Join with single spaces between words, but preserve multiple spaces between sentences
  String result = '';
  bool prevWasSpace = false;

  for (final part in parts) {
    if (part.trim().isNotEmpty && !prevWasSpace) {
      result += ' ';
      prevWasSpace = true;
    } else {
      prevWasSpace = false;
    }
    result += part;
  }

  // Trim leading/trailing whitespace
  return result.trim();
}
