import 'dart:io';

String wordsInSentence(String sentence) {
  if (sentence == null || sentence.isEmpty) return '';

  List<String> words = [];
  int i = 0;
  while (i < sentence.length) {
    // Skip whitespace
    while (i < sentence.length && sentence[i].isWhitespace) {
      i++;
    }

    if (i >= sentence.length) break;

    // Find the end of a word
    int j = i + 1;
    while (j < sentence.length && !sentence[j].isWhitespace) {
      j++;
    }

    String word = sentence.substring(i, j);
    words.add(word);
    i = j;
  }

  return words.join(' ');
}
