  if (n == 0 || n == 1) return n;

  // Calculate the position of the leftmost bit that is different between x and y
  int diff = x ^ y;
  int leftMostBitPosition = -1;
  for (int i = 31; i >= 0; i--) {
    if ((diff >> i) & 1 == 1) {
      leftMostBitPosition = i;
      break;
