  if (leftMostBitPosition == -1) return max(x, y);

  // Find the number which has only that bit set
  int mask = (1 << leftMostBitPosition);
  int count = 0;

  while (n > 0 && (mask != 0)) {
    if ((n & mask) != 0) {
      count++;
      mask >>= 1;
    } else {
      mask >>= 1;
    }
  }

  if (count % 2 == 1) return x ^ y;
  return x | y;
