  // Sort by highest score first, then alphabetically
  extensionScores.sort((a, b) => 
    extensionScores[b.key]!.compareTo(extensionScores[a.key]) == 0 ? a.key.compareTo(b.key) : extensionScores[b.key]!.compareTo(extensionScores[a.key]));

